const cfg = $input.first().json;
const registry = cfg.serviceRegistry || {};
const name = String(cfg.serviceName || '');
const svc = Object.prototype.hasOwnProperty.call(registry, name) ? registry[name] : null;

const rawPath = String(cfg.requestPath || '');
const pathOk = rawPath === '' || (rawPath.startsWith('/') && !rawPath.startsWith('//') && !rawPath.includes('..') && !rawPath.includes('://'));

const serviceKnown = !!svc && pathOk;
const safeName = name.replace(/[^a-zA-Z0-9_-]/g, '');

return [{
  json: {
    ...cfg,
    serviceKnown,
    unknownReason: !svc ? 'unknown_service' : (!pathOk ? 'invalid_path' : null),
    safeName,
    targetUrl: svc ? String(svc.baseUrl).replace(/\/$/, '') + rawPath : null,
    upstreamHeaders: svc?.headers || {},
    baseLimit: Number(svc?.baseLimit ?? cfg.baseLimit),
    windowSeconds: Number(svc?.windowSeconds ?? cfg.windowSeconds),
    minLimit: Number(svc?.minLimit ?? cfg.minLimit),
    maxWaitSeconds: Number(svc?.maxWaitSeconds ?? cfg.maxWaitSeconds),
    stateKey: `rl:${safeName}:state`
  }
}];

const ctx = $('IF - Service Registered').first().json;
const raw = $input.first().json?.stateRaw;

let stored = null;
if (raw) {
  try { stored = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { stored = null; }
}

const now = Date.now();
const storedLimit = Number(stored?.limit);
const effectiveLimit = Math.min(ctx.baseLimit, Math.max(ctx.minLimit, Number.isFinite(storedLimit) && storedLimit > 0 ? storedLimit : ctx.baseLimit));

const blockedUntil = Number(stored?.blockedUntil) || 0;
const blocked = blockedUntil > now;
const bucket = Math.floor(now / 1000 / ctx.windowSeconds);

return [{
  json: {
    ...ctx,
    storedState: stored,
    effectiveLimit,
    blocked,
    bucket,
    counterKey: `rl:${ctx.safeName}:win:${bucket}`,
    retryAfterSeconds: blocked ? Math.ceil((blockedUntil - now) / 1000) : 0,
    reason: blocked ? 'upstream_backoff' : null
  }
}];

const ctx = $('IF - Upstream Backoff Active').first().json;
const redisResult = $input.first().json || {};

const nums = Object.values(redisResult).filter(v => typeof v === 'number' || (typeof v === 'string' && v.trim() !== '' && !isNaN(v)));
const count = nums.length ? Number(nums[0]) : 0; // Redis error -> fail open

const limit = ctx.effectiveLimit;
const allowed = count <= limit;
const remaining = Math.max(0, limit - count);

const nowSec = Date.now() / 1000;
const secondsToReset = Math.max(1, Math.ceil(ctx.windowSeconds - (nowSec % ctx.windowSeconds)));
const canWait = !allowed && secondsToReset <= ctx.maxWaitSeconds;
const delaySeconds = secondsToReset + Math.floor(Math.random() * 2); // 0-1s jitter to avoid a thundering herd

return [{
  json: {
    ...ctx,
    requestCount: count,
    quotaAllowed: allowed,
    remaining,
    secondsToReset,
    canWait,
    delaySeconds,
    reason: allowed ? null : 'rate_limit_exceeded',
    retryAfterSeconds: allowed ? 0 : secondsToReset
  }
}];

const ctx = $('Wait - Throttle Delay').first().json;
const redisResult = $input.first().json || {};

const nums = Object.values(redisResult).filter(v => typeof v === 'number' || (typeof v === 'string' && v.trim() !== '' && !isNaN(v)));
const count = nums.length ? Number(nums[0]) : 0; // Redis error -> fail open

const allowed = count <= ctx.effectiveLimit;

return [{
  json: {
    ...ctx,
    requestCount: count,
    quotaAllowed: allowed,
    remaining: Math.max(0, ctx.effectiveLimit - count),
    reason: allowed ? null : 'rate_limit_exceeded_after_wait',
    retryAfterSeconds: allowed ? 0 : ctx.windowSeconds
  }
}];

const ctx = $('JS - Compute Effective Limit').first().json;
const res = $input.first().json || {};
const now = Date.now();

// normalise headers
const headers = {};
for (const [k, v] of Object.entries(res.headers || {})) headers[k.toLowerCase()] = v;
const num = v => { const n = Number(Array.isArray(v) ? v[0] : v); return Number.isFinite(n) ? n : null; };

const status = Number(res.statusCode ?? 0);
const hasError = !!res.error;
const upstreamError = hasError ? (typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error))) : null;

// hints from the upstream API
const upLimit = num(headers['x-ratelimit-limit'] ?? headers['ratelimit-limit']);
const upRemaining = num(headers['x-ratelimit-remaining'] ?? headers['ratelimit-remaining']);
let retryAfter = null;
if (headers['retry-after'] !== undefined) {
  const n = num(headers['retry-after']);
  if (n !== null) retryAfter = n;
  else {
    const d = Date.parse(headers['retry-after']);
    if (!isNaN(d)) retryAfter = Math.max(0, Math.ceil((d - now) / 1000));
  }
}

const prev = ctx.storedState || {};
const currentLimit = ctx.effectiveLimit;
const prevBlockedUntil = Number(prev.blockedUntil) || 0;

let newLimit = currentLimit;
let blockedUntil = prevBlockedUntil > now ? prevBlockedUntil : 0;
let lastReason = prev.lastReason || null;
let lastAdjusted = Number(prev.lastAdjusted) || 0;
let adaptReason = null;

const canIncrease = now - lastAdjusted >= ctx.windowSeconds * 1000;

if (status === 429) {
  // multiplicative decrease + honour Retry-After
  newLimit = Math.max(ctx.minLimit, Math.floor(currentLimit * ctx.decreaseFactor));
  blockedUntil = now + (retryAfter ?? ctx.windowSeconds) * 1000;
  adaptReason = 'upstream_429';
} else if (hasError || status >= 500) {
  // upstream is unhealthy, not a rate-limit signal: leave the limit alone
} else if (upLimit && upLimit > 0 && upRemaining !== null && upRemaining / upLimit < 0.1) {
  newLimit = Math.max(ctx.minLimit, Math.floor(currentLimit * 0.8));
  adaptReason = 'upstream_nearly_exhausted';
} else if (canIncrease && currentLimit < ctx.baseLimit) {
  // additive increase back towards baseLimit
  const step = Math.max(1, Math.ceil(ctx.baseLimit * ctx.increaseStepPercent / 100));
  newLimit = Math.min(ctx.baseLimit, currentLimit + step);
  adaptReason = 'additive_increase';
}

if (adaptReason) { lastReason = adaptReason; lastAdjusted = now; }
const changed = newLimit !== currentLimit || blockedUntil !== prevBlockedUntil;

// how this request was admitted
let remainingAtCall = null;
let delayedSeconds = 0;
try {
  if ($('Wait - Throttle Delay').isExecuted) {
    delayedSeconds = Number($('JS - Evaluate Quota').first().json.delaySeconds) || 0;
    remainingAtCall = $('JS - Evaluate Post-Wait').first().json.remaining;
  } else {
    remainingAtCall = $('JS - Evaluate Quota').first().json.remaining;
  }
} catch (e) {}

return [{
  json: {
    ...ctx,
    upstreamStatus: status,
    upstreamBody: res.body ?? null,
    upstreamError,
    previousLimit: currentLimit,
    newLimit,
    adaptReason,
    changed,
    retryAfterSeconds: status === 429 ? (retryAfter ?? ctx.windowSeconds) : 0,
    delayedSeconds,
    remainingAtCall,
    stateValue: JSON.stringify({ limit: newLimit, blockedUntil, lastAdjusted, lastReason, updatedAt: now })
  }
}];

const ctx = $('JS - Adapt Limit').first().json;

return [{
  json: {
    success: ctx.upstreamStatus > 0 && ctx.upstreamStatus < 400,
    service: ctx.serviceName,
    retryAfterSeconds: ctx.retryAfterSeconds,
    upstream: {
      status: ctx.upstreamStatus,
      data: ctx.upstreamBody,
      error: ctx.upstreamError
    },
    rateLimit: {
      limit: ctx.newLimit,
      previousLimit: ctx.previousLimit,
      baseLimit: ctx.baseLimit,
      remaining: ctx.remainingAtCall,
      windowSeconds: ctx.windowSeconds,
      throttledSeconds: ctx.delayedSeconds,
      adapted: ctx.changed,
      adaptReason: ctx.adaptReason
    }
  }
}];
